command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="8ab54f79fc2fd22b152697edaf4a66bacf559f6f"
$candidate="75fd920cee5468127de3f405e4dcf5f6d5e48fb6"
$branch="work/remote-evidence-fetch-fix-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("remote-evidence-fetch-fix-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_remote_windows_task_contract.py
  if($LASTEXITCODE -ne 0){throw "static check failed"}
  & python -X utf8 tests\winui\test_remote_windows_task_contract.py
  if($LASTEXITCODE -ne 0){throw "workflow contract failed"}
  & git diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "diff check failed"}
  Write-Host "REMOTE_EVIDENCE_FETCH_FIX_PREMERGE_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
